#include <iostream>
#include <map>
#include <vector>
#include <string>
#include <utility>
static int _hong = 0;
static void ok(bool dk, const char* ten) {
  if (!dk) { std::cout << "SAI: " << ten << "\n"; _hong++; }
}
static bool hopLe(const std::vector<std::string>& r,
                  const std::vector<std::pair<std::string,std::string>>& e) {
  std::map<std::string,int> vt;
  for (size_t i = 0; i < r.size(); i++) vt[r[i]] = (int)i;
  for (const auto& c : e) {
    if (!vt.count(c.first) || !vt.count(c.second)) return false;
    if (vt[c.first] >= vt[c.second]) return false;
  }
  return true;
}
int main() {
  std::vector<std::pair<std::string,std::string>> e1 = {{"a","b"},{"b","c"},{"a","c"}};
  auto r1 = sapXepTopo(e1);
  ok(r1.size() == 3, "du 3 dinh");
  ok(hopLe(r1, e1), "thu tu topo hop le");
  std::vector<std::pair<std::string,std::string>> e2 = {{"a","b"},{"b","c"},{"c","a"}};
  ok(sapXepTopo(e2).empty(), "CHU TRINH => rong");
  std::vector<std::pair<std::string,std::string>> e3 = {{"x","y"},{"p","q"}};
  auto r3 = sapXepTopo(e3);
  ok(r3.size() == 4, "hai thanh phan roi nhau, du 4 dinh");
  ok(hopLe(r3, e3), "hai thanh phan van hop le");
  // ★ CA PHAN BIET: chu trinh LAN voi mot thanh phan sap duoc. Kahn se xuat ra x,y roi dung.
  //   Ban THIEU kiem "ra.size() == dinh.size()" tra [x,y] (SAI); ban DUNG tra rong.
  //   Thieu ca nay thi doi chung khong phan biet duoc — da do: fake-bad LOT 1/3.
  std::vector<std::pair<std::string,std::string>> e5 = {{"x","y"},{"a","b"},{"b","c"},{"c","a"}};
  ok(sapXepTopo(e5).empty(), "CHU TRINH lan voi thanh phan sap duoc => VAN phai rong");
  std::vector<std::pair<std::string,std::string>> e4 = {{"a","a"}};
  ok(sapXepTopo(e4).empty(), "tu-vong cung la CHU TRINH");
  std::cout << (_hong == 0 ? "PASS" : "FAIL") << "\n";
  return _hong == 0 ? 0 : 1;
}

